// --- ClientPortal.view.tsx ---
import { Button } from '@microteia/ui';



/**
 * The Client record IN THE PORTAL, contributed by `portalView({ collection, surface: 'detail' }, ...)`.
 * The portal draws "Back" around it; this file only draws what the view model returns.
 */
export default function ClientPortal(props: { collection: string; recordId?: string }) {
  const vm = useClientPortalViewModel(props);

  return (
    <S.Wrapper>
      <S.Header>
        <S.Title>{vm.title}</S.Title>
        {vm.city && <S.Muted>{vm.city}</S.Muted>}
      </S.Header>

      <S.Header>
        <S.Muted>{vm.t('portal.orders')}</S.Muted>
        {vm.canOrder && <Button size="sm" onClick={vm.order}>{vm.t('portal.orders.new')}</Button>}
      </S.Header>

      {!vm.loading && vm.items.length === 0 && <S.Muted>{vm.t('portal.orders.empty')}</S.Muted>}
      {vm.items.map((item) => (
        <S.Order key={item.id} type="button" onClick={() => vm.open(item.id)}>{item.text}</S.Order>
      ))}
    </S.Wrapper>
  );
}

// --- ClientPortal.viewmodel.tsx ---
import { useMemo } from 'react';
import { useT } from '@microteia/i18n';
import { usePortalNavigation, usePortalRecord, usePortalRecords, usePortalScreen } from '@microteia/portal';

/** The Orders collection — the installed key of this package's screen. */
const ORDER_COLLECTION = 'portalExampleOrder';

/**
 * Everything the page decides, so the view only draws. A portal view receives the open record as
 * props (`collection`, `recordId`) and asks @microteia/portal for the rest: it never reaches
 * @microteia/data — the guest has none of the organization's stores.
 */
export const useClientPortalViewModel = ({ collection, recordId }: { collection: string; recordId?: string }) => {
  const t = useT('com.microteia.portal-example');
  const client = usePortalRecord(collection, recordId ?? '');
  const orderScreen = usePortalScreen(ORDER_COLLECTION);
  const navigation = usePortalNavigation();

  // `parent` filters to the orders of THIS client — the same link the server stamped on each order.
  const orders = usePortalRecords(ORDER_COLLECTION, { parent: { collection, recordId: recordId ?? '' } });

  const items = useMemo(() => orders.records.map((order) => ({
    id: order.recordId,
    text: t('portal.orders.quantity', {
      count: String(order.data.quantity ?? 1),
      item: String(order.data.item ?? order.title),
    }),
  })), [orders.records, t]);

  return {
    t,
    title: client?.title ?? '',
    city: typeof client?.data.city === 'string' ? client.data.city : '',
    loading: orders.loading,
    items,
    // Only offered when the Orders screen lets guests create — the declaration decides, not the view.
    canOrder: !!orderScreen?.create && !!recordId,
    order: () => navigation.create(ORDER_COLLECTION, recordId),
    open: (orderId: string) => navigation.openRecord(ORDER_COLLECTION, orderId),
  };
};

// --- ClientPortal.styles.tsx ---
import { styled } from 'styled-components';

/** Every colour, size and space comes from the theme. */
const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
  gap: ${({ theme }) => theme.spacing.md};
`;

const Header = styled.div`
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: ${({ theme }) => theme.spacing.sm};
  flex-wrap: wrap;
`;

const Title = styled.h2`
  font-size: ${({ theme }) => theme.fontSizes.xl};
  font-weight: 700;
  color: ${({ theme }) => theme.colors.text};
`;

const Muted = styled.p`
  font-size: ${({ theme }) => theme.fontSizes.sm};
  color: ${({ theme }) => theme.colors.textMuted};
`;

const Order = styled.button`
  display: block;
  width: 100%;
  text-align: left;
  padding: ${({ theme }) => theme.spacing.md};
  border: 1px solid ${({ theme }) => theme.colors.border};
  border-radius: ${({ theme }) => theme.borderRadius.md};
  background: ${({ theme }) => theme.colors.surface};
  color: ${({ theme }) => theme.colors.text};
  cursor: pointer;
`;

export const S = { Wrapper, Header, Title, Muted, Order };

import { styled } from 'styled-components';
import { useT } from '@microteia/i18n';
import { usePortalRecords } from '@microteia/portal';

const Count = styled.span`
  font-weight: 700;
  font-size: ${({ theme }) => theme.fontSizes['2xl']};
  color: ${({ theme }) => theme.colors.text};
`;

const Caption = styled.p`
  font-size: ${({ theme }) => theme.fontSizes.sm};
  color: ${({ theme }) => theme.colors.textMuted};
`;

/**
 * A card on the portal home: how many orders the guest has. Small on purpose — a card shares the row
 * with others on a computer and takes the whole width on a phone, so it never sets a width of its own.
 */
export default function OpenOrdersWidget() {
  const t = useT('com.microteia.portal-example');
  const { records, loading } = usePortalRecords('portalExampleOrder');

  return (
    <div>
      <Count>{loading ? '…' : records.length}</Count>
      <Caption>{t('portal.widget.orders.caption')}</Caption>
    </div>
  );
}
